import pdfplumber

pdf = pdfplumber.open('/app/25-26学年第一学期课程表.pdf')

targets = ['七大模块', '思政B', '思政A', '公共艺术', '形势与政策']
page_map = {}

for p in range(len(pdf.pages)):
    text = pdf.pages[p].extract_text() or ''
    for t in targets:
        if t in text:
            if t not in page_map:
                page_map[t] = []
            page_map[t].append(p + 1)
    if p % 50 == 0:
        print(f'Checked up to page {p+1}')

for t in sorted(page_map.keys()):
    print(f'{t}: PDF pages {page_map[t]}')

pdf.close()
